-- 0012 (2026-09-30): fixes from the launch validation. Safe to run more than once; every statement stands alone.
-- Grains given cooked in a recipe are bought dry ("2 tasses de riz cuit" -> about ⅔ tasse de riz).
alter table ingredients add column if not exists cooked_ratio numeric;
-- The recipe book must keep at least one member (someone who can change its recipes).
drop policy if exists "leave household" on household_members;
create policy "leave household" on household_members for delete using (user_id = auth.uid() and not (household_id = book_household() and (select count(*) from household_members m where m.household_id = household_members.household_id) <= 1));
-- Catalogue: new items (ground ginger, brown rice, white balsamic, mild chili…), safer aliases, 540 ml cans = 500 ml drained,
-- spinach in 200 g bags, broth shown as asked, more pantry items.
-- Generated by scripts/build-seed.ts. Global ingredient catalogue (idempotent).
update ingredients set name = 'Chou frisé (kale)' where household_id is null and name = 'Kale' and not exists (select 1 from ingredients x where x.household_id is null and x.name = 'Chou frisé (kale)');
update ingredients set name = 'Croustilles de maïs' where household_id is null and name = 'Chips de maïs' and not exists (select 1 from ingredients x where x.household_id is null and x.name = 'Croustilles de maïs');
update ingredients set name = 'Croustilles de pita' where household_id is null and name = 'Chips de pita' and not exists (select 1 from ingredients x where x.household_id is null and x.name = 'Croustilles de pita');
update ingredients set name = 'Sauce barbecue' where household_id is null and name = 'Sauce BBQ' and not exists (select 1 from ingredients x where x.household_id is null and x.name = 'Sauce barbecue');
update ingredients set name = 'Pâte de fèves pimentée (doubanjiang)' where household_id is null and name = 'Doubanjiang' and not exists (select 1 from ingredients x where x.household_id is null and x.name = 'Pâte de fèves pimentée (doubanjiang)');
update ingredients set name = 'Édamames' where household_id is null and name = 'Edamames' and not exists (select 1 from ingredients x where x.household_id is null and x.name = 'Édamames');
