update ingredients i set aisle = c.aisle, pantry = c.pantry, ml_per_can = c.ml_per_can, count_unit = c.count_unit, equiv = c.equiv, name_en = c.name_en, cooked_ratio = c.cooked_ratio from c where i.household_id is null and i.name = c.name;

-- One item for plant milks: "Boisson de soya" merges into "Boisson végétale" (recipes, lists, learned aliases).
update recipe_ingredients set ingredient_id = (select id from ingredients where household_id is null and name = 'Boisson végétale') where ingredient_id = (select id from ingredients where household_id is null and name = 'Boisson de soya') and (select id from ingredients where household_id is null and name = 'Boisson végétale') is not null;
update shopping_items set ingredient_id = (select id from ingredients where household_id is null and name = 'Boisson végétale') where ingredient_id = (select id from ingredients where household_id is null and name = 'Boisson de soya') and (select id from ingredients where household_id is null and name = 'Boisson végétale') is not null;
update ingredient_aliases set ingredient_id = (select id from ingredients where household_id is null and name = 'Boisson végétale') where household_id is not null and ingredient_id = (select id from ingredients where household_id is null and name = 'Boisson de soya') and (select id from ingredients where household_id is null and name = 'Boisson végétale') is not null;
delete from ingredients where household_id is null and name = 'Boisson de soya' and (select id from ingredients where household_id is null and name = 'Boisson végétale') is not null;
